reference_solution:
def count_valid_zero_walk_selections(nums):
    total=sum(nums);left=0;answer=0
    for value in nums:
        right=total-left-value
        if value==0:
            if left==right:answer+=2
            elif abs(left-right)==1:answer+=1
        left+=value
    return answer

